// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));
        vm.assume(caller != c.DEPOSITOR_ACCOUNT());
        vm.prank(caller);
        bool ok = true;
        try c.setL1BlockValues(1, 1, 1, bytes32(0), 1, bytes32(0), 1, 1) {
            ok = true;
        } catch {
            ok = false;
        }
        // Reference: only depositorAccount passes; bug: any address == DEPOSITOR_ACCOUNT passes, others still fail
        // But caller != DEPOSITOR_ACCOUNT, so caller also != initial depositorAccount (unless changed)
        // The property: a non-DEPOSITOR_ACCOUNT caller must always revert
        assertFalse(ok);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address internal constant DEPOSITOR_ACCOUNT = 0xDeaDDEaDDeAdDeAdDEAdDEaddeAddEAdDEAd0001;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint64 _number, uint64 _timestamp, uint256 _basefee, bytes32 _hash, uint64 _sequenceNumber, bytes32 _batcherHash, uint256 _l1FeeOverhead, uint256 _l1FeeScalar) public {
        // Ensure we test both the constant address and other random callers so the fuzzer can expose the difference
        // No assume needed; any address is admissible.
        vm.prank(caller);
        try c.setL1BlockValues(_number, _timestamp, _basefee, _hash, _sequenceNumber, _batcherHash, _l1FeeOverhead, _l1FeeScalar) {
            // Call succeeded; the caller must be the current depositorAccount (reference behavior)
            // depositorAccount defaults to address(0), so the only legitimate non-reverting caller is address(0).
            // If caller == DEPOSITOR_ACCOUNT, it should revert on the reference but succeeds in the mutant.
            assertTrue(caller == c.depositorAccount());
        } catch {
            // Call reverted; caller must NOT be the current depositorAccount
            assertTrue(caller != c.depositorAccount());
        }
    }
}
